const cfg = $('Config (API key + CVs base)').first().json;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const g = j.generar;
  const marcada = g === true || g === 1 ||
    ['true', 'x', '✓', 'verdadero', 'si', 'sí', '1']
      .includes(String(g ?? '').trim().toLowerCase());
  const yaTiene = String(j.cv_adaptado || '').trim().length > 0;
  if (!marcada || yaTiene || !j.url) continue;
  const cvBase = cfg.cvs_base[j.perfil_sugerido] || cfg.cvs_base['Administrativo'];
  out.push({ json: { ...j, cv_base: cvBase } });
}
return out;

const inp = $input.first().json;
const cfg = $('Config (API key + CVs base)').first().json;
const prompt = inp.prompt;

let texto = '';
let goErr = '';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://opencode.ai/zen/go/v1/messages',
    headers: {
      'x-api-key': cfg.opencode_api_key,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: {
      model: 'minimax-m3',
      max_tokens: 2000,
      messages: [{ role: 'user', content: prompt }]
    },
    json: true
  });
  texto = (resp.content || [])
    .filter(c => c.type === 'text')
    .map(c => c.text || '')
    .join('')
    .trim();
  if (!texto) goErr = 'Go sin texto: ' + JSON.stringify(resp).slice(0, 200);
} catch (e) {
  goErr = (e.message || String(e)).slice(0, 200);
}

if (!texto) {
  texto = 'ERROR al generar: ' + (goErr || 'sin respuesta de la IA');
}

return [{ json: { url: inp.url, cv_adaptado: texto } }];

const ctx = $('Loop ofertas').item.json;
const docId = $('Crear Google Doc').item.json.documentId;
const scoring = $('Extraer nuevo match').item.json;
return [{ json: {
  url: ctx.url,
  titulo: ctx.titulo,
  empresa: ctx.empresa,
  cv_adaptado: 'https://docs.google.com/document/d/' + docId + '/edit',
  match_pct: scoring.match_pct,
  ats_tip: scoring.ats_tip
}}];

// Convierte el CV con marcadores (TITULO:/CONTACTO:/SECCION:/"- ") en:
//  1) el texto plano final (fullText) que se inserta de una sola vez en el Doc
//  2) la lista de requests de formato (negrita, tamaños, bullets) de la Google Docs API,
//     calculados con los indices exactos de caracteres dentro de fullText.
// Todo se manda en UN solo batchUpdate: primero el insertText, y como ese request se
// ejecuta primero, los requests de formato de ahi en mas ya pueden usar indices fijos.

const docId = $('Crear Google Doc').item.json.documentId;
const raw = ($('Extraer texto del CV').item.json.cv_adaptado || '').replace(/\r\n/g, '\n');
const lineasRaw = raw.split('\n');

let fullText = '';
const segmentos = []; // {start, end, tipo}
let bulletBuffer = null;

function agregar(texto, tipo) {
  const start = fullText.length;
  fullText += texto;
  const end = fullText.length;
  if (tipo) segmentos.push({ start, end, tipo });
  return { start, end };
}

function cerrarBullets() {
  if (bulletBuffer) {
    segmentos.push({ start: bulletBuffer.start, end: bulletBuffer.end, tipo: 'bullet' });
    bulletBuffer = null;
  }
}

for (let i = 0; i < lineasRaw.length; i++) {
  const linea = lineasRaw[i];

  if (/^TITULO:/i.test(linea)) {
    cerrarBullets();
    agregar(linea.replace(/^TITULO:\s*/i, ''), 'titulo');
    agregar('\n');
    continue;
  }
  if (/^CONTACTO:/i.test(linea)) {
    cerrarBullets();
    agregar(linea.replace(/^CONTACTO:\s*/i, ''), 'contacto');
    agregar('\n');
    continue;
  }
  if (/^SECCION:/i.test(linea)) {
    cerrarBullets();
    agregar('\n');
    agregar(linea.replace(/^SECCION:\s*/i, '').trim(), 'seccion');
    agregar('\n');
    continue;
  }
  if (/^\s*-\s+/.test(linea)) {
    const texto = linea.replace(/^\s*-\s+/, '');
    const { end } = agregar(texto);
    agregar('\n');
    if (!bulletBuffer) bulletBuffer = { start: end - texto.length };
    bulletBuffer.end = end + 1;
    continue;
  }
  if (linea.trim() === '') {
    cerrarBullets();
    agregar('\n');
    continue;
  }
  cerrarBullets();
  agregar(linea, 'body');
  agregar('\n');
}
cerrarBullets();

if (!fullText.trim()) fullText = '(No se pudo generar el CV, revisar el error en la columna cv_adaptado antes de este paso.)\n';

const requests = [
  { insertText: { location: { index: 1 }, text: fullText } }
];

for (const s of segmentos) {
  const startIndex = s.start + 1;
  const endIndex = s.end + 1;
  if (startIndex >= endIndex) continue;
  const range = { startIndex, endIndex };

  if (s.tipo === 'titulo') {
    requests.push({ updateTextStyle: { range, textStyle: { bold: true, fontSize: { magnitude: 16, unit: 'PT' } }, fields: 'bold,fontSize' } });
  } else if (s.tipo === 'contacto') {
    requests.push({ updateTextStyle: { range, textStyle: { italic: true, fontSize: { magnitude: 9.5, unit: 'PT' }, foregroundColor: { color: { rgbColor: { red: 0.35, green: 0.35, blue: 0.35 } } } }, fields: 'italic,fontSize,foregroundColor' } });
  } else if (s.tipo === 'seccion') {
    requests.push({ updateTextStyle: { range, textStyle: { bold: true, fontSize: { magnitude: 12, unit: 'PT' }, foregroundColor: { color: { rgbColor: { red: 0.10, green: 0.25, blue: 0.55 } } } }, fields: 'bold,fontSize,foregroundColor' } });
    requests.push({ updateParagraphStyle: { range, paragraphStyle: { spaceAbove: { magnitude: 10, unit: 'PT' }, spaceBelow: { magnitude: 3, unit: 'PT' }, borderBottom: { width: { magnitude: 0.5, unit: 'PT' }, padding: { magnitude: 1, unit: 'PT' }, dashStyle: 'SOLID', color: { color: { rgbColor: { red: 0.75, green: 0.75, blue: 0.75 } } } } }, fields: 'spaceAbove,spaceBelow,borderBottom' } });
  } else if (s.tipo === 'body') {
    requests.push({ updateTextStyle: { range, textStyle: { fontSize: { magnitude: 10.5, unit: 'PT' } }, fields: 'fontSize' } });
  } else if (s.tipo === 'bullet') {
    requests.push({ updateTextStyle: { range, textStyle: { fontSize: { magnitude: 10.5, unit: 'PT' } }, fields: 'fontSize' } });
    requests.push({ createParagraphBullets: { range, bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE' } });
  }
}

return [{ json: { documentId: docId, requests } }];

const ctx = $('Loop ofertas').item.json;
const desc = $('Armar prompt').item.json.desc || '';
const cvAdaptado = $json.cv_adaptado || '';

const prompt = [
  'Sos un evaluador de compatibilidad entre un CV y una oferta laboral.',
  'Devolve SOLAMENTE un JSON valido, en una sola linea, sin markdown y sin backticks, con este formato exacto:',
  '{"match": <numero entero 0-100>, "tip": "<max 15 palabras: que keyword de la oferta conviene sumar o resaltar en el CV>"}',
  '',
  '=== CV DEL CANDIDATO (version ya adaptada a esta oferta) ===',
  cvAdaptado,
  '',
  '=== OFERTA ===',
  'Puesto: ' + (ctx.titulo || ''),
  'Empresa: ' + (ctx.empresa || ''),
  'Descripcion: ' + desc
].join('\n');

return [{ json: { url: ctx.url, cv_adaptado: cvAdaptado, prompt, match_pct_previo: ctx.match_pct, ats_tip_previo: ctx.ats_tip } }];

const inp = $input.first().json;
const cfg = $('Config (API key + CVs base)').first().json;
const prompt = inp.prompt;

let texto = '';
let goErr = '';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://opencode.ai/zen/go/v1/messages',
    headers: {
      'x-api-key': cfg.opencode_api_key,
      'anthropic-version': '2023-06-01',
      'content-type': 'application/json'
    },
    body: {
      model: 'minimax-m3',
      max_tokens: 300,
      messages: [{ role: 'user', content: prompt }]
    },
    json: true
  });
  texto = (resp.content || [])
    .filter(c => c.type === 'text')
    .map(c => c.text || '')
    .join('')
    .trim();
  if (!texto) goErr = 'Go sin texto: ' + JSON.stringify(resp).slice(0, 200);
} catch (e) {
  goErr = (e.message || String(e)).slice(0, 200);
}

let match_pct = (inp.match_pct_previo !== undefined && inp.match_pct_previo !== null && inp.match_pct_previo !== '') ? inp.match_pct_previo : '';
let ats_tip = inp.ats_tip_previo || '';

if (texto) {
  try {
    const jm = texto.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(jm ? jm[0] : texto);
    if (parsed.match !== undefined && parsed.match !== null) {
      match_pct = Number(parsed.match);
      ats_tip = parsed.tip || '';
    }
  } catch (e) {
    // no se pudo interpretar: dejamos el match/tip que la fila ya tenia
  }
} else if (match_pct === '') {
  ats_tip = 'ERROR Go: ' + goErr;
}

return [{ json: { url: inp.url, cv_adaptado: inp.cv_adaptado, match_pct, ats_tip } }];

