// El trigger corre cada 10 min; si generar un CV (IA + Google Doc) tarda mas que eso,
// una corrida nueva podria arrancar mientras la anterior sigue viva y duplicar CVs.
// Guardamos un timestamp de 'corriendo desde' y nos salteamos esta corrida si todavia
// esta vigente. Expira solo a los 20 min por si una corrida anterior quedo colgada
// (ej: crasheo a mitad de camino) para no bloquear el workflow para siempre.
const sd = $getWorkflowStaticData('global');
const ahora = Date.now();
if (sd.procesandoDesde && (ahora - sd.procesandoDesde) < 20 * 60 * 1000) {
  return [];
}
sd.procesandoDesde = ahora;
return $input.all();
